<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, auth } from '@/services/auth'
import type { AvailableLab } from '@/services/portal'
interface User {id:string;username:string;person_id:string;display_name:string;role:string;active:number;system_admin:number;lab_ids:string}
const users=ref<User[]>([]),labs=ref<AvailableLab[]>([]),keyword=ref(''),error=ref(''),message=ref(''),busy=ref(false)
const selected=ref<User|null>(null),role=ref('user'),active=ref(true),scopes=ref<string[]>([]),temporary=ref('')
const filtered=computed(()=>users.value.filter(u=>(u.display_name+u.username).includes(keyword.value)))
async function load(){try{[users.value,labs.value]=await Promise.all([api<User[]>('/api/admin/users'),api<AvailableLab[]>('/api/labs/available')])}catch(e){error.value=(e as Error).message}}
function select(u:User){selected.value=u;role.value=u.role;active.value=!!u.active;scopes.value=JSON.parse(u.lab_ids) as string[];temporary.value='';message.value='';error.value=''}
async function save(){if(!selected.value)return;busy.value=true;error.value='';try{await api(`/api/admin/users/${selected.value.id}`,{method:'PATCH',body:JSON.stringify({active:active.value,role:role.value,labIds:scopes.value})});message.value='账号已更新，原会话已失效';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function reset(){if(!selected.value)return;busy.value=true;error.value='';try{const r=await api<{temporaryPassword:string}>(`/api/admin/users/${selected.value.id}/reset-password`,{method:'POST'});temporary.value=r.temporaryPassword;message.value='临时密码仅显示本次，请通过可信渠道交付'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="space-y-5"><h1 class="text-3xl">账号与权限</h1><p class="text-ink-3">人员身份与系统权限分别维护。修改权限或停用后，账号需要重新登录。</p><p v-if="error" role="alert" class="text-err">{{ error }}</p><p v-if="message" role="status" class="text-ok">{{ message }}</p><div class="grid lg:grid-cols-2 gap-5"><section class="panel p-4"><input v-model="keyword" class="input mb-4" aria-label="搜索账号" placeholder="搜索姓名或账号"><div class="max-h-[65vh] overflow-y-auto"><button v-for="u in filtered" :key="u.id" class="w-full text-left p-3 border-b border-line hover:bg-page" @click="select(u)"><span>{{ u.display_name }} <span class="text-xs text-ink-3">{{ u.username }}</span></span><span class="float-right text-xs">{{ u.active?(u.role==='admin'?'管理员':'普通用户'):'已停用' }}</span></button></div></section><section v-if="selected" class="panel p-6 self-start space-y-4"><h2 class="text-xl">{{ selected.display_name }} · {{ selected.username }}</h2><p v-if="selected.id===auth.user?.id||selected.system_admin" class="text-ink-3">系统管理账号由部署维护流程管理。可在个人门户修改本人密码。</p><template v-else><label class="block"><span class="label">角色</span><select v-model="role" class="input"><option value="user">普通用户</option><option value="admin">管理员</option></select></label><label class="flex gap-2"><input v-model="active" type="checkbox">启用账号</label><fieldset v-if="role==='admin'"><legend class="label">负责实验室</legend><label v-for="l in labs" :key="l.labId" class="flex gap-2 text-sm py-1"><input v-model="scopes" type="checkbox" :value="l.labId">{{ l.labName }}</label></fieldset><div class="flex gap-3"><button class="btn-primary" :disabled="busy" @click="save">保存权限</button><button class="btn-default" :disabled="busy" @click="reset">重置临时密码</button></div></template><p v-if="temporary" class="p-4 bg-page break-all select-all">临时密码：{{ temporary }}</p></section></div></div></template>
